// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount1, uint256 amount2) public {
        amount1 = bound(amount1, 1, type(uint128).max);
        amount2 = bound(amount2, 1, type(uint128).max);

        address user1 = makeAddr("user1");
        address user2 = makeAddr("user2");
        vm.deal(user1, amount1);
        vm.deal(user2, amount2);

        vm.prank(user1);
        c.addToBalance{value: amount1}();

        vm.prank(user2);
        c.addToBalance{value: amount2}();

        vm.prank(user1);
        c.withdrawBalance();

        vm.prank(user2);
        c.withdrawBalance();

        uint256 sumBalances = c.getBalance(user1) + c.getBalance(user2);
        assertEq(address(c).balance, sumBalances);
    }
}
